    <table class="legal-table">
      <thead><tr><th>Situation</th><th>Notre démarche</th><th>Précision</th></tr></thead>
      <tbody>
        <tr><td>Défaut de fabrication ou de fonctionnement NFC</td><td>Examen et solution appropriée</td><td>Réparation, remplacement, remboursement ou autre recours applicable selon la situation et la loi.</td></tr>
